CREATE TYPE campaign_status AS ENUM ('DRAFT','ACTIVE','PAUSED','ARCHIVED');
CREATE TABLE campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,status campaign_status NOT NULL DEFAULT 'DRAFT',starts_at timestamptz,ends_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT campaign_window CHECK(ends_at IS NULL OR starts_at IS NULL OR ends_at>starts_at));
CREATE TABLE coupons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),campaign_id uuid REFERENCES campaigns(id),code text NOT NULL UNIQUE,discount_type text NOT NULL CHECK(discount_type IN('FIXED_TRY','PERCENT')),discount_value numeric(12,2) NOT NULL CHECK(discount_value>=0),usage_limit integer,used_count integer NOT NULL DEFAULT 0,starts_at timestamptz,ends_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE coupon_redemptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),coupon_id uuid NOT NULL REFERENCES coupons(id),order_id uuid REFERENCES orders(id),customer_id uuid REFERENCES customers(id),discount_amount numeric(12,2) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(coupon_id,order_id));
